    [StructLayout(LayoutKind.Explicit, Size = 32)]
    public unsafe partial struct LtHit
    {
        [FieldOffset(0)] public LtVec3 pos;
        [FieldOffset(12)] public LtVec3 normal;
        /// <summary>
        /// How far along the segment, 0..1.
        /// </summary>
        [FieldOffset(24)] public float t;
        /// <summary>
        /// `LT_SURFACE_TERRAIN`, or the cover's `LT_COVER_*`.
        /// </summary>
        [FieldOffset(28)] public byte surface;
    }

    /// <summary>
    /// The plugin's functions, bound by name from the loaded library.
    /// </summary>
    public unsafe struct LtApi
    {
        /// <summary>
        /// The API's version (`VERSION`): the C# side checks it, and the layout
        /// hash, when it loads the plugin.
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<uint> lt_version;
        /// <summary>
        /// A hash of every exported struct's layout and function's signature.
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<ulong> lt_layout_hash;
        /// <summary>
        /// The last error on this thread (a failed connect, a caught panic):
        /// copied into `buf`; returns its length in bytes.
        /// (byte* buf, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<byte*, int, int> lt_last_error;
        /// <summary>
        /// Connects to `addr` ("host:port") with a dev connect token for `user`,
        /// minted with the server's `--token-key` (`key_hex`: 64 hex digits, or
        /// null for the public dev key) and `--server-id`. `cfg` may be null.
        /// Null on failure (`lt_last_error`).
        /// (byte* addr, ulong user, byte* key_hex, ulong server_id, LtConfig* cfg)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<byte*, ulong, byte*, ulong, LtConfig*, IntPtr> lt_connect_dev;
        /// <summary>
        /// Connects with a playtest invite (`lattice-invite`): the server, who we
        /// are, and the next of its connect tokens (each connects once; the
        /// invite's `.used` file beside it counts them). Null on failure.
        /// (byte* path, LtConfig* cfg)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<byte*, LtConfig*, IntPtr> lt_connect_invite;
        /// <summary>
        /// Disconnects (the server hears at once) and frees the session (its net
        /// thread stopped first).
        /// (IntPtr s)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, void> lt_close;
        /// <summary>
        /// Starts a frame: reads the plugin's clock once; every call until the
        /// next frame uses it. Returns seconds since connecting.
        /// (IntPtr s)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, double> lt_begin_frame;
        /// <summary>
        /// Starts a frame `secs` after connecting (for tests that drive time).
        /// (IntPtr s, double secs)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, double, double> lt_begin_frame_at;
        /// <summary>
        /// Receives and delivers everything that arrived; returns the state
        /// (`LT_STATE_*`). On the net thread, the thread receives: this only
        /// returns the state.
        /// (IntPtr s)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, int> lt_poll;
        /// <summary>
        /// The connection's state (`LT_STATE_*`).
        /// (IntPtr s)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, int> lt_state;
        /// <summary>
        /// Pulls the trigger. Returns 1 if a shot fired (the rifle was ready, we
        /// are alive), with its direction and tracer origin in `out` (may be
        /// null); its tracer flies at once. Call before `lt_inputs`: the shot
        /// rides this frame's input.
        /// (IntPtr s, LtFire* fire, LtShot* out)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtFire*, LtShot*, int> lt_fire;
        /// <summary>
        /// This frame's intent to the input clock: inputs (with any shot) go out
        /// at the server's pace. On the net thread, the thread makes them from
        /// the latest intent, every tick, frames or not.
        /// (IntPtr s, LtIntent* intent)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtIntent*, void> lt_inputs;
        /// <summary>
        /// Our own player: where to draw it, its vitals, the server ghost and
        /// the reticle's cone (`ads`: down the sights).
        /// (IntPtr s, byte ads, LtOwn* out)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, byte, LtOwn*, void> lt_own;
        /// <summary>
        /// Draws every other player at this frame's render step: fills `out` (up
        /// to `cap`) and returns how many there are. Exactly once per frame.
        /// (IntPtr s, LtEntity* out, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtEntity*, int, int> lt_render;
        /// <summary>
        /// The newest sample of every player, undelayed (server ghosts): fills
        /// `out` (up to `cap`), returns how many it wrote.
        /// (IntPtr s, LtEntity* out, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtEntity*, int, int> lt_ghosts;
        /// <summary>
        /// This frame's combat, after `lt_render`: news to events, shots starting
        /// as their shooters are drawn firing, tracers flown to now (with their
        /// impacts). Then drain `lt_events`, `lt_fx` and read `lt_tracers`.
        /// (IntPtr s)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, void> lt_combat;
        /// <summary>
        /// Moves up to `cap` combat events into `out`, oldest first; returns how
        /// many it moved.
        /// (IntPtr s, LtEvent* out, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtEvent*, int, int> lt_events;
        /// <summary>
        /// Moves up to `cap` effects (shots drawn firing, impacts) into `out`,
        /// oldest first; returns how many it moved.
        /// (IntPtr s, LtFx* out, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtFx*, int, int> lt_fx;
        /// <summary>
        /// Every tracer in flight, as streaks: fills `out` (up to `cap`) and
        /// returns how many there are.
        /// (IntPtr s, LtTracer* out, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtTracer*, int, int> lt_tracers;
        /// <summary>
        /// Where others' drawn muzzles are from their eyes (meters right, up and
        /// forward of their aim): their tracers leave from there.
        /// (IntPtr s, LtVec3* offset)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtVec3*, void> lt_set_others_muzzle;
        /// <summary>
        /// End of the frame: packets out. On the net thread, the thread sends:
        /// this does nothing.
        /// (IntPtr s)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, void> lt_flush;
        /// <summary>
        /// The net graph's numbers.
        /// (IntPtr s, LtStats* out)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtStats*, void> lt_stats;
        /// <summary>
        /// Gaps between the last snapshots' arrivals (ms, oldest first): fills
        /// `out` (up to `cap`), returns how many it wrote.
        /// (IntPtr s, float* out, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, float*, int, int> lt_snapshot_gaps;
        /// <summary>
        /// The report for `lattice-report.txt` (who, where, then the
        /// connection's numbers): copied into `buf`; returns its length.
        /// (IntPtr s, byte* buf, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, byte*, int, int> lt_summary;
        /// <summary>
        /// A world from a seed (the server's is in its Welcome), shared with any
        /// session in the process that uses it. Free with `lt_world_free`.
        /// (ulong seed)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<ulong, IntPtr> lt_world_new;
        /// <summary>
        /// The session's world, once welcomed (else null). Free with
        /// `lt_world_free`.
        /// (IntPtr s)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, IntPtr> lt_session_world;
        /// <summary>
        /// (IntPtr w)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, void> lt_world_free;
        /// <summary>
        /// (IntPtr w, LtWorldInfo* out)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtWorldInfo*, void> lt_world_info;
        /// <summary>
        /// Terrain heights (m) of the `nx` × `ny` samples from sample (`x0`,
        /// `y0`), row by row (y north), into `out`; samples past the edge repeat
        /// it. Returns how many it wrote.
        /// (IntPtr w, int x0, int y0, int nx, int ny, float* out)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, int, int, int, int, float*, int> lt_world_heights;
        /// <summary>
        /// Every cover box: fills `out` (up to `cap`), returns how many there are.
        /// (IntPtr w, LtBox* out, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtBox*, int, int> lt_world_boxes;
        /// <summary>
        /// Every base and outpost: fills `out` (up to `cap`), returns how many.
        /// (IntPtr w, LtSite* out, int cap)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtSite*, int, int> lt_world_sites;
        /// <summary>
        /// The terrain's height at (`x`, `y`), as movement samples it.
        /// (IntPtr w, float x, float y)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, float, float, float> lt_world_height;
        /// <summary>
        /// The highest surface at (`x`, `y`) feet at `z` can stand on: the
        /// terrain, or a box's top no higher than `z + reach`.
        /// (IntPtr w, float x, float y, float z, float reach)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, float, float, float, float, float> lt_world_ground;
        /// <summary>
        /// Where the segment `from` -&gt; `to` first hits the ground or cover
        /// (shots' rules): 1 and `out` filled, or 0.
        /// (IntPtr w, LtVec3* from, LtVec3* to, LtHit* out)
        /// </summary>
        [NonSerialized] public delegate* unmanaged[Cdecl]<IntPtr, LtVec3*, LtVec3*, LtHit*, int> lt_world_raycast;

        /// <summary>
        /// Binds every function through `proc` (name to address); returns the names it couldn't find.
        /// </summary>
        public string Bind(Func<string, IntPtr> proc)
        {
            var missing = new System.Text.StringBuilder();
            IntPtr p;
            p = proc("lt_version"); if (p == IntPtr.Zero) missing.Append(" lt_version"); lt_version = (delegate* unmanaged[Cdecl]<uint>)(void*)p;
            p = proc("lt_layout_hash"); if (p == IntPtr.Zero) missing.Append(" lt_layout_hash"); lt_layout_hash = (delegate* unmanaged[Cdecl]<ulong>)(void*)p;
            p = proc("lt_last_error"); if (p == IntPtr.Zero) missing.Append(" lt_last_error"); lt_last_error = (delegate* unmanaged[Cdecl]<byte*, int, int>)(void*)p;
            p = proc("lt_connect_dev"); if (p == IntPtr.Zero) missing.Append(" lt_connect_dev"); lt_connect_dev = (delegate* unmanaged[Cdecl]<byte*, ulong, byte*, ulong, LtConfig*, IntPtr>)(void*)p;
            p = proc("lt_connect_invite"); if (p == IntPtr.Zero) missing.Append(" lt_connect_invite"); lt_connect_invite = (delegate* unmanaged[Cdecl]<byte*, LtConfig*, IntPtr>)(void*)p;
            p = proc("lt_close"); if (p == IntPtr.Zero) missing.Append(" lt_close"); lt_close = (delegate* unmanaged[Cdecl]<IntPtr, void>)(void*)p;
            p = proc("lt_begin_frame"); if (p == IntPtr.Zero) missing.Append(" lt_begin_frame"); lt_begin_frame = (delegate* unmanaged[Cdecl]<IntPtr, double>)(void*)p;
            p = proc("lt_begin_frame_at"); if (p == IntPtr.Zero) missing.Append(" lt_begin_frame_at"); lt_begin_frame_at = (delegate* unmanaged[Cdecl]<IntPtr, double, double>)(void*)p;
            p = proc("lt_poll"); if (p == IntPtr.Zero) missing.Append(" lt_poll"); lt_poll = (delegate* unmanaged[Cdecl]<IntPtr, int>)(void*)p;
            p = proc("lt_state"); if (p == IntPtr.Zero) missing.Append(" lt_state"); lt_state = (delegate* unmanaged[Cdecl]<IntPtr, int>)(void*)p;
            p = proc("lt_fire"); if (p == IntPtr.Zero) missing.Append(" lt_fire"); lt_fire = (delegate* unmanaged[Cdecl]<IntPtr, LtFire*, LtShot*, int>)(void*)p;
            p = proc("lt_inputs"); if (p == IntPtr.Zero) missing.Append(" lt_inputs"); lt_inputs = (delegate* unmanaged[Cdecl]<IntPtr, LtIntent*, void>)(void*)p;
            p = proc("lt_own"); if (p == IntPtr.Zero) missing.Append(" lt_own"); lt_own = (delegate* unmanaged[Cdecl]<IntPtr, byte, LtOwn*, void>)(void*)p;
            p = proc("lt_render"); if (p == IntPtr.Zero) missing.Append(" lt_render"); lt_render = (delegate* unmanaged[Cdecl]<IntPtr, LtEntity*, int, int>)(void*)p;
            p = proc("lt_ghosts"); if (p == IntPtr.Zero) missing.Append(" lt_ghosts"); lt_ghosts = (delegate* unmanaged[Cdecl]<IntPtr, LtEntity*, int, int>)(void*)p;
            p = proc("lt_combat"); if (p == IntPtr.Zero) missing.Append(" lt_combat"); lt_combat = (delegate* unmanaged[Cdecl]<IntPtr, void>)(void*)p;
            p = proc("lt_events"); if (p == IntPtr.Zero) missing.Append(" lt_events"); lt_events = (delegate* unmanaged[Cdecl]<IntPtr, LtEvent*, int, int>)(void*)p;
            p = proc("lt_fx"); if (p == IntPtr.Zero) missing.Append(" lt_fx"); lt_fx = (delegate* unmanaged[Cdecl]<IntPtr, LtFx*, int, int>)(void*)p;
            p = proc("lt_tracers"); if (p == IntPtr.Zero) missing.Append(" lt_tracers"); lt_tracers = (delegate* unmanaged[Cdecl]<IntPtr, LtTracer*, int, int>)(void*)p;
            p = proc("lt_set_others_muzzle"); if (p == IntPtr.Zero) missing.Append(" lt_set_others_muzzle"); lt_set_others_muzzle = (delegate* unmanaged[Cdecl]<IntPtr, LtVec3*, void>)(void*)p;
            p = proc("lt_flush"); if (p == IntPtr.Zero) missing.Append(" lt_flush"); lt_flush = (delegate* unmanaged[Cdecl]<IntPtr, void>)(void*)p;
            p = proc("lt_stats"); if (p == IntPtr.Zero) missing.Append(" lt_stats"); lt_stats = (delegate* unmanaged[Cdecl]<IntPtr, LtStats*, void>)(void*)p;
            p = proc("lt_snapshot_gaps"); if (p == IntPtr.Zero) missing.Append(" lt_snapshot_gaps"); lt_snapshot_gaps = (delegate* unmanaged[Cdecl]<IntPtr, float*, int, int>)(void*)p;
            p = proc("lt_summary"); if (p == IntPtr.Zero) missing.Append(" lt_summary"); lt_summary = (delegate* unmanaged[Cdecl]<IntPtr, byte*, int, int>)(void*)p;
            p = proc("lt_world_new"); if (p == IntPtr.Zero) missing.Append(" lt_world_new"); lt_world_new = (delegate* unmanaged[Cdecl]<ulong, IntPtr>)(void*)p;
            p = proc("lt_session_world"); if (p == IntPtr.Zero) missing.Append(" lt_session_world"); lt_session_world = (delegate* unmanaged[Cdecl]<IntPtr, IntPtr>)(void*)p;
            p = proc("lt_world_free"); if (p == IntPtr.Zero) missing.Append(" lt_world_free"); lt_world_free = (delegate* unmanaged[Cdecl]<IntPtr, void>)(void*)p;
            p = proc("lt_world_info"); if (p == IntPtr.Zero) missing.Append(" lt_world_info"); lt_world_info = (delegate* unmanaged[Cdecl]<IntPtr, LtWorldInfo*, void>)(void*)p;
            p = proc("lt_world_heights"); if (p == IntPtr.Zero) missing.Append(" lt_world_heights"); lt_world_heights = (delegate* unmanaged[Cdecl]<IntPtr, int, int, int, int, float*, int>)(void*)p;
            p = proc("lt_world_boxes"); if (p == IntPtr.Zero) missing.Append(" lt_world_boxes"); lt_world_boxes = (delegate* unmanaged[Cdecl]<IntPtr, LtBox*, int, int>)(void*)p;
            p = proc("lt_world_sites"); if (p == IntPtr.Zero) missing.Append(" lt_world_sites"); lt_world_sites = (delegate* unmanaged[Cdecl]<IntPtr, LtSite*, int, int>)(void*)p;
            p = proc("lt_world_height"); if (p == IntPtr.Zero) missing.Append(" lt_world_height"); lt_world_height = (delegate* unmanaged[Cdecl]<IntPtr, float, float, float>)(void*)p;
            p = proc("lt_world_ground"); if (p == IntPtr.Zero) missing.Append(" lt_world_ground"); lt_world_ground = (delegate* unmanaged[Cdecl]<IntPtr, float, float, float, float, float>)(void*)p;
            p = proc("lt_world_raycast"); if (p == IntPtr.Zero) missing.Append(" lt_world_raycast"); lt_world_raycast = (delegate* unmanaged[Cdecl]<IntPtr, LtVec3*, LtVec3*, LtHit*, int>)(void*)p;
            return missing.ToString().Trim();
        }
    }
}
